verification_tests:
from target import points_earned


def test_single_amount():
    assert points_earned([100], 0.1) == 10


def test_points_are_rounded_per_amount():
    # 55 * 0.1 = 5.5 -> 6, 55 * 0.1 = 5.5 -> 6 => 12
    assert points_earned([55, 55], 0.1) == 12


def test_empty_amounts_give_zero():
    assert points_earned([], 0.1) == 0
